{
  "mode": "server",
  "server": "pocketmockster",
  "serverStatus": "ready",
  "tools": [
    {
      "tool": "pm_battle",
      "description": "Run the current battle to completion automatically (handles menus, forced switches, move-learning prompts). Returns all battle messages plus outcome: \"win\" | \"lose\" | \"caught\" | \"run\". Only call when state.mode == \"battle\".",
      "inputSchema": {
        "type": "object",
        "properties": {
          "preferMoves": {
            "description": "move ids to prefer, in priority order (e.g. [\"vinewhip\",\"tackle\"])",
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "moveIndex": {
            "description": "always use the move at this slot if it has PP",
            "type": "integer",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "maxTurns": {
            "type": "integer",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          }
        },
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_continue",
      "description": "Resume the game from its autosave (title screen -> CONTINUE) instead of starting over. Use this when a previous session left progress behind; it fails if no save exists.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_debug",
      "description": "God-mode debug actions for TESTING ONLY (never for legitimate playthrough validation): setSeed(n), noEncounters(on), warp(map,x,y), setPartyLevels(level), givemon(species,level), setHp(idx,hp), addItem(item,n), healAll(), setTime(minute), addExp(idx,amount), hatchEggs(), walk(steps), drainPP(idx), clearSave().",
      "inputSchema": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string"
          },
          "args": {
            "type": "array",
            "items": {}
          }
        },
        "required": [
          "action"
        ],
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_grind",
      "description": "Level up efficiently: paces over grass and auto-runs every wild battle until the lead reaches targetLevel or the battle budget is spent. Stand on or next to a grass tile first (see pm_map, \"G\"). Returns battles/wins/losses, resulting levels, and stoppedBecause (\"target-level\" | \"max-battles\" | \"blackout\" | \"step-budget\"). Far cheaper than looping pm_walk yourself.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "targetLevel": {
            "description": "stop once the lead mon reaches this level",
            "type": "integer",
            "minimum": 2,
            "maximum": 100
          },
          "maxBattles": {
            "description": "battle budget, default 12",
            "type": "integer",
            "minimum": 1,
            "maximum": 40
          },
          "preferMoves": {
            "description": "move ids to prefer while battling",
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_map",
      "description": "Get the current map grid: tiles (T=tree/wall, W=water, G=grass with wild encounters, .=floor, ,=path, D=door/warp), warps (with destinations), NPC positions, items, signs, and your position. Use it to plan paths around obstacles.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_new_game",
      "description": "Start a fresh game: clears the save, skips intro dialogue, talks to the professor and picks a starter. Ends in the overworld of the lab with the starter in party, wild encounters enabled. Call this first (or pm_continue to resume a save).",
      "inputSchema": {
        "type": "object",
        "properties": {
          "seed": {
            "description": "RNG seed for reproducibility",
            "type": "integer",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "starterIndex": {
            "description": "0 = sproutle (grass, default), 1 = cindercub (fire), 2 = puddlefin (water)",
            "type": "integer",
            "minimum": 0,
            "maximum": 2
          },
          "noEncounters": {
            "description": "disable random wild encounters (default true)",
            "type": "boolean"
          }
        },
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_press",
      "description": "Press GBA-style buttons. a = confirm/talk/advance text, b = cancel/back, start = open menu, arrows = move cursor or face a direction. Batch multiple keys in one call (e.g. [\"down\",\"down\",\"a\"]).",
      "inputSchema": {
        "type": "object",
        "properties": {
          "keys": {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "up",
                "down",
                "left",
                "right",
                "a",
                "b",
                "start"
              ]
            },
            "description": "ordered list of keys to press"
          }
        },
        "required": [
          "keys"
        ],
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_report_finding",
      "description": "File a structured finding that a developer can act on without asking you follow-up questions. The server automatically attaches a screenshot, the current game state, the seed, and your preceding tool calls, so do not restate those. area (which codebase owns it) - choose carefully, a wrong area sends the fix to the wrong files: - game: the RPG itself (rules, maps, dialogue, battle math, progression, balance) - harness: the pm_* tools you are calling (wrong/stale tool results, automation that plays badly, tool errors). pm_battle uses a FIXED scripted policy, it is NOT the game AI, so complaints about move choice during pm_battle are harness, not game. - docs: a tool description or documented contract disagrees with real behavior - environment: the page reloaded, the server restarted, playwright errors like \"execution context was destroyed\" - infrastructure, not the game severity: blocker (cannot progress / crash / data loss), major (wrong behavior with a workaround), minor, polish, good (praise worth keeping), question (behavior you cannot classify without design intent - use this instead of guessing \"bug\"). Filing the same issue twice is fine: identical findings are deduplicated into one entry with an occurrence count.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "title": {
            "type": "string",
            "description": "one line, specific: \"walking left from (8,9) in mapletown reports blocked but moves\""
          },
          "severity": {
            "type": "string",
            "enum": [
              "blocker",
              "major",
              "minor",
              "polish",
              "good",
              "question"
            ]
          },
          "category": {
            "type": "string",
            "enum": [
              "crash",
              "softlock",
              "progression",
              "logic",
              "balance",
              "ux",
              "text",
              "collision",
              "performance",
              "tooling"
            ]
          },
          "area": {
            "type": "string",
            "enum": [
              "game",
              "harness",
              "docs",
              "environment"
            ]
          },
          "expected": {
            "type": "string",
            "description": "what should have happened"
          },
          "actual": {
            "type": "string",
            "description": "what actually happened, with concrete values"
          },
          "detail": {
            "description": "extra analysis: your hypothesis about the cause, what you ruled out, exact steps if unusual",
            "type": "string"
          },
          "reproduced": {
            "description": "true only if you deliberately repeated the steps and saw it again",
            "type": "boolean"
          }
        },
        "required": [
          "title",
          "severity",
          "category",
          "area",
          "expected",
          "actual"
        ],
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_report_note",
      "description": "Record a free-form observation that is not a finding (progress commentary, context for later). For anything a developer should fix, use pm_report_finding instead.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string"
          }
        },
        "required": [
          "text"
        ],
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_set_speed",
      "description": "Set game speed multiplier (0.25-20). Higher = faster animations/timers. Use high speed (4-8) for grinding/traversal, low speed (1-2) for precision menus.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "multiplier": {
            "type": "number",
            "minimum": 0.25,
            "maximum": 20
          }
        },
        "required": [
          "multiplier"
        ],
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_state",
      "description": "Get the full game state: mode (title/overworld/dialogue/menu/battle/ending), position, money, badges, party (species/level/hp/moves/status), menu contents, battle status, pokedex counts.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_wait",
      "description": "Wait until a given mode is reached (e.g. \"overworld\" after dialogue) or, without arguments, until movement finishes.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "mode": {
            "type": "string"
          },
          "timeoutMs": {
            "type": "integer",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          }
        },
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    },
    {
      "tool": "pm_walk",
      "description": "Walk in a direction for N tiles. Returns from/to positions and walked (tiles actually moved). Stops early if blocked (blocked:true, i.e. a wall/NPC) or if a battle/dialogue interrupts (interrupted:<mode>). The to position is authoritative: all tools are serialized server-side, so results never race with pm_state. Prefer this over repeated pm_press for movement.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "direction": {
            "type": "string",
            "enum": [
              "up",
              "down",
              "left",
              "right"
            ]
          },
          "tiles": {
            "type": "integer",
            "minimum": 1,
            "maximum": 60
          }
        },
        "required": [
          "direction",
          "tiles"
        ],
        "$schema": "http://json-schema.org/draft-07/schema#"
      }
    }
  ]
}
